/**
 * Starts a child that opens `file`, signals through the pipe that it is open
 * (or failed) and keeps it open for hold_ms.
 */
pid_t start_holder( const std::string & file, int hold_ms, bool & opened )
{
    int fds[2];

    if( ::pipe( fds ) != 0 ) {
        opened = false;
        return -1;
    }

    const pid_t child = ::fork();

    if( child == 0 ) {
        ::close( fds[0] );

        const int fd = ::open( file.c_str(), O_RDONLY );
        const char c = fd >= 0 ? 'y' : 'n';

        ssize_t ignored = ::write( fds[1], &c, 1 );
        (void)ignored;

        ::usleep( (useconds_t)hold_ms * 1000 );

        if( fd >= 0 ) {
            ::close( fd );
        }

        ::_exit( 0 );
    }

    ::close( fds[1] );

    char c = 'n';
    ssize_t ignored = ::read( fds[0], &c, 1 );
    (void)ignored;
    ::close( fds[0] );

    opened = ( c == 'y' );
    return child;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
void stop_holder( pid_t child )
{
    if( child > 0 ) {
        ::kill( child, SIGKILL );
        int status = 0;
        ::waitpid( child, &status, 0 );
    }
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

