std::shared_ptr<TestCaseBase<bool>> test_case_filebusy_detects_open_file()
{
    return std::make_shared<TestCaseFuncNoInp>( __FUNCTION__, true, []() {
        const std::string file = write_test_file( "filebusy_detect", "a;b;c\n" );

        bool opened = false;
        const pid_t child = start_holder( file, 3000, opened );

        const std::vector<pid_t> pids = processes_using_file( file );
        const bool found = std::find( pids.begin(), pids.end(), child ) != pids.end();

        stop_holder( child );

        // our own process is not a holder
        const std::vector<pid_t> after = processes_using_file( file );

        return opened && found && after.empty();
    });
}
