std::shared_ptr<TestCaseBase<bool>> test_case_filebusy_waits()
{
    return std::make_shared<TestCaseFuncNoInp>( __FUNCTION__, true, []() {
        const std::string file = write_test_file( "filebusy_wait", "a;b;c\n" );

        bool opened = false;
        const pid_t child = start_holder( file, 800, opened );

        const auto begin = std::chrono::steady_clock::now();

        const bool free = wait_until_file_is_free( file, 50, 10 );

        const long elapsed_ms = (long)std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - begin ).count();

        stop_holder( child );

        return opened
            && free
            && elapsed_ms >= 500                 // really waited for the holder
            && processes_using_file( file ).empty();
    });
}
