std::shared_ptr<TestCaseBase<bool>> test_case_filebusy_lock()
{
    return std::make_shared<TestCaseFuncNoInp>( __FUNCTION__, true, []() {
        const std::string lock_file = ".test_filebusy.lock";

        FileLock first;
        const bool got_first = first.tryLock( lock_file );

        bool got_second = true;

        {
            FileLock second;
            got_second = second.tryLock( lock_file );   // must fail
        }

        first.unlock();

        bool got_after = false;

        {
            FileLock third;
            got_after = third.tryLock( lock_file );     // released again
        }

        return got_first && !got_second && got_after;
    });
}
