std::shared_ptr<TestCaseBase<bool>> test_case_filebusy_modified()
{
    return std::make_shared<TestCaseFuncNoInp>( __FUNCTION__, true, []() {
        const std::string file = write_test_file( "filebusy_modified", "a\nb\n" );

        const FileState before = file_state( file );

        // unchanged
        const bool unchanged = !file_was_modified( before, file_state( file ) );

        // appended to
        {
            std::ofstream out( file, std::ios::binary | std::ios::app );
            out << "c\n";
        }
        const bool appended = file_was_modified( before, file_state( file ) );

        // rewritten in place with the same size
        const FileState appended_state = file_state( file );
        {
            std::ofstream out( file, std::ios::binary | std::ios::trunc );
            out << "x\ny\nz\n";
        }
        const bool rewritten = file_was_modified( appended_state, file_state( file ) );

        // truncated
        const FileState rewritten_state = file_state( file );
        {
            std::ofstream out( file, std::ios::binary | std::ios::trunc );
            out << "x\n";
        }
        const bool shrunk = file_was_modified( rewritten_state, file_state( file ) );

        return before.valid && unchanged && appended && rewritten && shrunk;
    });
}
